package workbench.vthreads.l06

import java.util.concurrent.Callable
import java.util.concurrent.ExecutionException
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors
import java.util.concurrent.Semaphore
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicInteger

/**
 * 300 quote requests arrive at once. Each borrows a connection from a 10-connection pool for a
 * 5 ms query (the pool gives up after 30 ms of waiting), then makes a 100 ms FX call.
 * The same handler runs three ways: the old fixed pool, a plain swap to virtual threads,
 * and virtual threads with a Semaphore in front of the database.
 */
private const val REQUESTS = 300
private const val CONNECTIONS = 10

private val pool = Semaphore(CONNECTIONS)                       // the fake connection pool
private val fxInFlight = AtomicInteger()
private val fxPeak = AtomicInteger()

private fun query(): String {
    check(pool.tryAcquire(30, TimeUnit.MILLISECONDS)) { "connection pool: no connection after 30 ms" }
    try {
        Thread.sleep(5)                                         // the query
        return "standard"
    } finally {
        pool.release()
    }
}

private fun fxRate(): String {
    fxPeak.accumulateAndGet(fxInFlight.incrementAndGet()) { a, b -> maxOf(a, b) }
    try {
        Thread.sleep(100)                                       // the FX call
        return "1.0842"
    } finally {
        fxInFlight.decrementAndGet()
    }
}

private fun run(label: String, executor: ExecutorService, handler: () -> String) {
    fxPeak.set(0)
    var ok = 0
    var failed = 0
    val t0 = System.nanoTime()
    executor.use {
        val futures = List(REQUESTS) { executor.submit(Callable { handler() }) }
        for (f in futures) {
            try {
                f.get()
                ok++
            } catch (e: ExecutionException) {
                failed++
            }
        }
    }
    println("%-34s %,6d ms   ok %3d   failed %3d   FX calls in flight at peak %3d"
        .format(label, (System.nanoTime() - t0) / 1_000_000, ok, failed, fxPeak.get()))
}

fun main() {
    // A: today: 10 platform threads, sized to the pool
    run("A: fixed pool of 10", Executors.newFixedThreadPool(10)) { query() + fxRate() }

    // B: the one-line migration: nothing limits the database any more
    run("B: virtual threads", Executors.newVirtualThreadPerTaskExecutor()) { query() + fxRate() }

    // C: virtual threads, and the limit made explicit around the database call only
    val dbPermits = Semaphore(CONNECTIONS, true)
    run("C: virtual threads + Semaphore(10)", Executors.newVirtualThreadPerTaskExecutor()) {
        dbPermits.acquire()
        val tier = try {
            query()
        } finally {
            dbPermits.release()
        }
        tier + fxRate()
    }
}

sections.body:
Most services don't create their request threads themselves. The framework does, so the switch is in the framework.

**Quarkus** has no global switch. You opt in per endpoint, or per class, with `@RunOnVirtualThread`, and Quarkus then runs each call on a new virtual thread:

```java
@Path("/quotes")
public class QuoteResource {
    @Inject QuoteService quotes;

    @POST
    @RunOnVirtualThread                       // each call runs on a new virtual thread
    public Quote quote(QuoteRequest request) {
        return quotes.quote(request);         // plain blocking code: JDBC, REST client, Kafka producer
    }
}
```

```kotlin
@Path("/quotes")
class QuoteResource(private val quotes: QuoteService) {

    @POST
    @RunOnVirtualThread                       // each call runs on a new virtual thread
    fun quote(request: QuoteRequest): Quote =
        quotes.quote(request)                 // plain blocking code: JDBC, REST client, Kafka producer
}
```

The annotation is `io.smallrye.common.annotation.RunOnVirtualThread`. The same annotation works on Reactive Messaging `@Incoming` methods, which is how a Kafka consumer handles records on virtual threads. Opting in one endpoint at a time is a good fit for a migration: you move the busiest blocking endpoint first and compare.

**Spring Boot** 3.2 and later has one property for the whole application:

```properties
spring.threads.virtual.enabled=true
```

With it, the embedded web server handles requests on virtual threads, and Spring's own task executors use them too.

Neither framework adds the limits from the checklist. That's still your code. They also change what an old setting means. `quarkus.thread-pool.max-threads` sizes the worker pool, which `@RunOnVirtualThread` endpoints don't use, so it no longer caps them. If you relied on it as your database limit, that limit is gone, exactly like the pool in the lab.

The Quarkus guide lists the traps it sees most, and you know all of them by now: libraries that pin on JDK 21, CPU-heavy endpoints that monopolize a carrier, and libraries that pool objects in `ThreadLocal`s.

