public final class QuoteService implements AutoCloseable {
    private final CustomerDb db;
    private final FxApi fx;
    // 1. one new virtual thread per request: no size to pick
    private final ExecutorService requests = Executors.newVirtualThreadPerTaskExecutor();
    // 2. the limit the old pool gave you by accident, now explicit
    private final Semaphore dbPermits;

    public QuoteService(CustomerDb db, FxApi fx) {
        this.db = db;
        this.fx = fx;
        this.dbPermits = new Semaphore(db.poolSize(), true);   // one permit per pooled connection
    }

    public Quote quote(QuoteRequest r) throws Exception {
        String tier;
        dbPermits.acquire();                                    // outside the try
        try {
            tier = db.tier(r.customerId());                     // only the database call holds a permit
        } finally {
            dbPermits.release();
        }
        BigDecimal rate = fx.rate(r.pair());                    // FX calls overlap freely
        return new Quote(r.customerId(), r.pair(), rate, fee(tier, r.amount()));
    }

    // 3. a gauge for the dashboard
    public int dbWaiting() {
        return dbPermits.getQueueLength();
    }

    @Override
    public void close() {
        requests.close();                                       // 4. waits for requests in flight
    }
}

