class QuoteService(private val db: CustomerDb, private val fx: FxApi) : AutoCloseable {
    // 1. one new virtual thread per request: no size to pick
    private val requests = Executors.newVirtualThreadPerTaskExecutor()
    // 2. the limit the old pool gave you by accident, now explicit
    private val dbPermits = Semaphore(db.poolSize, true)       // one permit per pooled connection

    fun quote(r: QuoteRequest): Quote {
        val tier = withDbPermit { db.tier(r.customerId) }      // only the database call holds a permit
        val rate = fx.rate(r.pair)                             // FX calls overlap freely
        return Quote(r.customerId, r.pair, rate, fee(tier, r.amount))
    }

    // 3. a gauge for the dashboard
    fun dbWaiting(): Int = dbPermits.queueLength

    override fun close() = requests.close()                    // 4. waits for requests in flight

    private inline fun <T> withDbPermit(block: () -> T): T {
        dbPermits.acquire()                                    // outside the try
        try {
            return block()
        } finally {
            dbPermits.release()
        }
    }
}

