final class LedgerClient {
    private final LedgerDb ledgerDb;
    private final Semaphore permits;                       // one per pooled connection, shared by all callers

    LedgerClient(LedgerDb ledgerDb, int connections) {
        this.ledgerDb = ledgerDb;
        this.permits = new Semaphore(connections, true);
    }

    void post(Entry entry) throws InterruptedException {
        if (!permits.tryAcquire(200, TimeUnit.MILLISECONDS)) {   // a deadline, not an endless wait
            throw new LedgerBusyException("no ledger connection within 200 ms");
        }
        try {
            ledgerDb.insert(entry);                        // only this call holds a permit
        } finally {
            permits.release();
        }
    }

    int waiting() {                                        // the metric: callers queued right now
        return permits.getQueueLength();
    }
}

